假設 fork() 與 pthread_create() 都成功，下列程式的輸出是什麼？
<pre class="code">int x = 1;
void *f(void *a) { x *= 3; return NULL; }

int main(void) {
  pthread_t t;
  pid_t pid = fork();
  if (pid == 0) {
    pthread_create(&amp;t, NULL, f, NULL);
    pthread_join(t, NULL);
    x += 1;
    printf("C %d\n", x);
    exit(0);
  }
  wait(NULL);
  pthread_create(&amp;t, NULL, f, NULL);
  pthread_join(t, NULL);
  printf("P %d\n", x);
  return 0;
}</pre>

